CREATE TABLE dbo.Warehouses (
  WarehouseId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Warehouses_Id DEFAULT NEWSEQUENTIALID(), BranchId UNIQUEIDENTIFIER NOT NULL,
  Code VARCHAR(30) NOT NULL, Name NVARCHAR(150) NOT NULL, IsActive BIT NOT NULL CONSTRAINT DF_Warehouses_Active DEFAULT 1,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Warehouses_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Warehouses PRIMARY KEY(WarehouseId), CONSTRAINT FK_Warehouses_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId),
  CONSTRAINT UQ_Warehouses_Branch_Code UNIQUE(BranchId, Code)
);
CREATE TABLE dbo.Items (
  ItemId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Items_Id DEFAULT NEWSEQUENTIALID(), Code VARCHAR(40) NOT NULL, Name NVARCHAR(200) NOT NULL,
  BaseUnit VARCHAR(30) NOT NULL, ConversionFactor DECIMAL(18,6) NOT NULL CONSTRAINT DF_Items_Conversion DEFAULT 1,
  IsSerialized BIT NOT NULL CONSTRAINT DF_Items_Serialized DEFAULT 0, RequiresLot BIT NOT NULL CONSTRAINT DF_Items_Lot DEFAULT 1,
  IsActive BIT NOT NULL CONSTRAINT DF_Items_Active DEFAULT 1, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Items_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Items PRIMARY KEY(ItemId), CONSTRAINT UQ_Items_Code UNIQUE(Code), CONSTRAINT CK_Items_Conversion CHECK(ConversionFactor > 0)
);
CREATE TABLE dbo.GoodsReceipts (
  GoodsReceiptId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_GoodsReceipts_Id DEFAULT NEWSEQUENTIALID(), ReceiptNo VARCHAR(40) NOT NULL,
  WarehouseId UNIQUEIDENTIFIER NOT NULL, SupplierId UNIQUEIDENTIFIER NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_GoodsReceipts_Status DEFAULT 'DRAFT',
  ReceivedAt DATETIME2 NULL, InspectedBy UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_GoodsReceipts_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_GoodsReceipts PRIMARY KEY(GoodsReceiptId), CONSTRAINT UQ_GoodsReceipts_No UNIQUE(ReceiptNo),
  CONSTRAINT FK_GoodsReceipts_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId), CONSTRAINT FK_GoodsReceipts_Supplier FOREIGN KEY(SupplierId) REFERENCES dbo.Suppliers(SupplierId),
  CONSTRAINT FK_GoodsReceipts_Inspector FOREIGN KEY(InspectedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_GoodsReceipts_Status CHECK(Status IN ('DRAFT','INSPECTED','POSTED','REJECTED','VOID'))
);
CREATE TABLE dbo.StockLots (
  StockLotId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_StockLots_Id DEFAULT NEWSEQUENTIALID(), ItemId UNIQUEIDENTIFIER NOT NULL,
  WarehouseId UNIQUEIDENTIFIER NOT NULL, GoodsReceiptId UNIQUEIDENTIFIER NULL, LotNumber VARCHAR(100) NOT NULL, ExpiryDate DATE NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_StockLots_Status DEFAULT 'QUARANTINED', UnitCost DECIMAL(18,4) NOT NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_StockLots_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_StockLots PRIMARY KEY(StockLotId), CONSTRAINT UQ_StockLots_Item_Warehouse_Lot UNIQUE(ItemId, WarehouseId, LotNumber),
  CONSTRAINT FK_StockLots_Item FOREIGN KEY(ItemId) REFERENCES dbo.Items(ItemId), CONSTRAINT FK_StockLots_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId),
  CONSTRAINT FK_StockLots_Receipt FOREIGN KEY(GoodsReceiptId) REFERENCES dbo.GoodsReceipts(GoodsReceiptId), CONSTRAINT CK_StockLots_Cost CHECK(UnitCost >= 0),
  CONSTRAINT CK_StockLots_Status CHECK(Status IN ('RELEASED','QUARANTINED','BLOCKED','RECALLED','EXPIRED','DEPLETED'))
);
CREATE TABLE dbo.StockSerials (
  StockSerialId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_StockSerials_Id DEFAULT NEWSEQUENTIALID(), StockLotId UNIQUEIDENTIFIER NOT NULL,
  SerialNumber VARCHAR(150) NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_StockSerials_Status DEFAULT 'AVAILABLE',
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_StockSerials_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_StockSerials PRIMARY KEY(StockSerialId), CONSTRAINT UQ_StockSerials_Number UNIQUE(SerialNumber),
  CONSTRAINT FK_StockSerials_Lot FOREIGN KEY(StockLotId) REFERENCES dbo.StockLots(StockLotId), CONSTRAINT CK_StockSerials_Status CHECK(Status IN ('AVAILABLE','RESERVED','CONSUMED','QUARANTINED','BLOCKED','RECALLED'))
);
CREATE TABLE dbo.StockBalances (
  StockBalanceId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_StockBalances_Id DEFAULT NEWSEQUENTIALID(), WarehouseId UNIQUEIDENTIFIER NOT NULL,
  ItemId UNIQUEIDENTIFIER NOT NULL, StockLotId UNIQUEIDENTIFIER NOT NULL, OnHand DECIMAL(18,4) NOT NULL CONSTRAINT DF_StockBalances_OnHand DEFAULT 0,
  Reserved DECIMAL(18,4) NOT NULL CONSTRAINT DF_StockBalances_Reserved DEFAULT 0, Quarantined DECIMAL(18,4) NOT NULL CONSTRAINT DF_StockBalances_Quarantine DEFAULT 0,
  Blocked DECIMAL(18,4) NOT NULL CONSTRAINT DF_StockBalances_Blocked DEFAULT 0, Available AS (OnHand - Reserved - Quarantined - Blocked) PERSISTED, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_StockBalances PRIMARY KEY(StockBalanceId), CONSTRAINT UQ_StockBalances_Scope UNIQUE(WarehouseId, ItemId, StockLotId),
  CONSTRAINT FK_StockBalances_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId), CONSTRAINT FK_StockBalances_Item FOREIGN KEY(ItemId) REFERENCES dbo.Items(ItemId),
  CONSTRAINT FK_StockBalances_Lot FOREIGN KEY(StockLotId) REFERENCES dbo.StockLots(StockLotId),
  CONSTRAINT CK_StockBalances_Amounts CHECK(OnHand >= 0 AND Reserved >= 0 AND Quarantined >= 0 AND Blocked >= 0 AND OnHand - Reserved - Quarantined - Blocked >= 0)
);
CREATE TABLE dbo.StockReservations (
  StockReservationId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_StockReservations_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  ServiceLineId UNIQUEIDENTIFIER NULL, WarehouseId UNIQUEIDENTIFIER NOT NULL, ItemId UNIQUEIDENTIFIER NOT NULL, StockLotId UNIQUEIDENTIFIER NOT NULL,
  StockSerialId UNIQUEIDENTIFIER NULL, Quantity DECIMAL(18,4) NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_StockReservations_Status DEFAULT 'RESERVED',
  ExpiresAt DATETIME2 NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_StockReservations_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_StockReservations PRIMARY KEY(StockReservationId), CONSTRAINT FK_StockReservations_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_StockReservations_ServiceLine FOREIGN KEY(ServiceLineId) REFERENCES dbo.ServiceLines(ServiceLineId), CONSTRAINT FK_StockReservations_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId),
  CONSTRAINT FK_StockReservations_Item FOREIGN KEY(ItemId) REFERENCES dbo.Items(ItemId), CONSTRAINT FK_StockReservations_Lot FOREIGN KEY(StockLotId) REFERENCES dbo.StockLots(StockLotId),
  CONSTRAINT FK_StockReservations_Serial FOREIGN KEY(StockSerialId) REFERENCES dbo.StockSerials(StockSerialId), CONSTRAINT CK_StockReservations_Quantity CHECK(Quantity > 0),
  CONSTRAINT CK_StockReservations_Status CHECK(Status IN ('RESERVED','CONSUMED','RELEASED','EXPIRED','CANCELLED'))
);
CREATE UNIQUE INDEX UX_StockReservations_ActiveSerial ON dbo.StockReservations(StockSerialId) WHERE StockSerialId IS NOT NULL AND Status='RESERVED';
CREATE TABLE dbo.StockMovements (
  StockMovementId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_StockMovements_Id DEFAULT NEWSEQUENTIALID(), WarehouseId UNIQUEIDENTIFIER NOT NULL,
  ItemId UNIQUEIDENTIFIER NOT NULL, StockLotId UNIQUEIDENTIFIER NOT NULL, StockSerialId UNIQUEIDENTIFIER NULL, StockReservationId UNIQUEIDENTIFIER NULL,
  MovementType VARCHAR(30) NOT NULL, Quantity DECIMAL(18,4) NOT NULL, UnitCost DECIMAL(18,4) NOT NULL,
  SourceEventId UNIQUEIDENTIFIER NOT NULL, OriginalId UNIQUEIDENTIFIER NULL, OccurredAt DATETIME2 NOT NULL CONSTRAINT DF_StockMovements_At DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_StockMovements PRIMARY KEY(StockMovementId), CONSTRAINT FK_StockMovements_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId),
  CONSTRAINT FK_StockMovements_Item FOREIGN KEY(ItemId) REFERENCES dbo.Items(ItemId), CONSTRAINT FK_StockMovements_Lot FOREIGN KEY(StockLotId) REFERENCES dbo.StockLots(StockLotId),
  CONSTRAINT FK_StockMovements_Serial FOREIGN KEY(StockSerialId) REFERENCES dbo.StockSerials(StockSerialId), CONSTRAINT FK_StockMovements_Reservation FOREIGN KEY(StockReservationId) REFERENCES dbo.StockReservations(StockReservationId),
  CONSTRAINT FK_StockMovements_Original FOREIGN KEY(OriginalId) REFERENCES dbo.StockMovements(StockMovementId), CONSTRAINT UQ_StockMovements_Source_Type UNIQUE(SourceEventId, MovementType, StockLotId),
  CONSTRAINT CK_StockMovements_Quantity CHECK(Quantity > 0), CONSTRAINT CK_StockMovements_Cost CHECK(UnitCost >= 0),
  CONSTRAINT CK_StockMovements_Type CHECK(MovementType IN ('RECEIPT','RESERVE','CONSUME','RELEASE','ADJUST_IN','ADJUST_OUT','TRANSFER_IN','TRANSFER_OUT','RECALL','DISPOSAL'))
);
CREATE TABLE dbo.Stocktakes (
  StocktakeId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Stocktakes_Id DEFAULT NEWSEQUENTIALID(), WarehouseId UNIQUEIDENTIFIER NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_Stocktakes_Status DEFAULT 'DRAFT', CountedAt DATETIME2 NULL, ApprovedBy UNIQUEIDENTIFIER NULL,
  ResultJson NVARCHAR(MAX) NOT NULL CONSTRAINT DF_Stocktakes_Result DEFAULT '{}', CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Stocktakes_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_Stocktakes PRIMARY KEY(StocktakeId), CONSTRAINT FK_Stocktakes_Warehouse FOREIGN KEY(WarehouseId) REFERENCES dbo.Warehouses(WarehouseId),
  CONSTRAINT FK_Stocktakes_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_Stocktakes_Json CHECK(ISJSON(ResultJson)=1),
  CONSTRAINT CK_Stocktakes_Status CHECK(Status IN ('DRAFT','COUNTED','APPROVED','POSTED','CANCELLED'))
);
CREATE TABLE dbo.LotRecalls (
  LotRecallId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_LotRecalls_Id DEFAULT NEWSEQUENTIALID(), StockLotId UNIQUEIDENTIFIER NOT NULL,
  Reason NVARCHAR(1000) NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_LotRecalls_Status DEFAULT 'OPEN', InitiatedAt DATETIME2 NOT NULL CONSTRAINT DF_LotRecalls_At DEFAULT SYSUTCDATETIME(),
  ClosedAt DATETIME2 NULL, CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_LotRecalls PRIMARY KEY(LotRecallId), CONSTRAINT FK_LotRecalls_Lot FOREIGN KEY(StockLotId) REFERENCES dbo.StockLots(StockLotId),
  CONSTRAINT CK_LotRecalls_Status CHECK(Status IN ('OPEN','PATIENT_REVIEW','RESOLVED','CLOSED'))
);
